  const sendToPrimary = () => {
    addLog(`Sending draft report to primary reviewer: ${PRIMARY_REVIEWER.name}...`);
    // Simulation
    setTimeout(() => {
      setStatus(AppStatus.SENT_TO_PRIMARY);
      addLog("Email sent to Jerry Hung for approval.");
