    // Simulation
    setTimeout(() => {
      setStatus(AppStatus.COMPLETED);
      addLog("Distribution complete. All recipients notified.");
    }, 2000);
  };

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setNews([]);
    setReport(null);
    setError(null);
    setLogs([]);
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
