           <button onClick={reset} className="bg-red-900/50 hover:bg-red-900 px-3 py-1 rounded text-sm transition-colors">Reset</button>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-4 lg:p-8 grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* Left Column: Workflow Controls & Logs */}
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <span className="w-2 h-6 bg-red-600 rounded-full"></span>
              Execution Workflow
