            <div className="space-y-4">
              {/* Step 1: News */}
              <div className={`p-4 rounded-xl border-2 transition-all ${news.length > 0 ? 'border-green-100 bg-green-50' : 'border-slate-100 bg-slate-50'}`}>
                <div className="flex justify-between items-center mb-2">
                  <span className="text-sm font-medium text-slate-500 uppercase tracking-wider">Step 1: Data Gathering</span>
                  {news.length > 0 && <span className="text-green-600 text-xs font-bold">✓ DONE</span>}
                </div>
                <button 
                  disabled={status === AppStatus.FETCHING_NEWS || news.length > 0}
                  onClick={fetchNews}
                  className={`w-full py-2 rounded-lg font-semibold flex items-center justify-center gap-2 transition-colors ${news.length > 0 ? 'bg-green-600 text-white opacity-50' : 'bg-red-700 text-white hover:bg-red-800'}`}
                >
                  {status === AppStatus.FETCHING_NEWS ? "Fetching..." : "Fetch News RSS"}
                </button>
                {news.length > 0 && <p className="text-xs mt-2 text-slate-500">{news.length} items loaded.</p>}
              </div>

              {/* Step 2: AI */}
              <div className={`p-4 rounded-xl border-2 transition-all ${report ? 'border-green-100 bg-green-50' : 'border-slate-100 bg-slate-50'}`}>
                <div className="flex justify-between items-center mb-2">
                  <span className="text-sm font-medium text-slate-500 uppercase tracking-wider">Step 2: AI Analysis</span>
                  {report && <span className="text-green-600 text-xs font-bold">✓ DONE</span>}
