                {status === AppStatus.COMPLETED && (
                  <div className="p-2 bg-green-100 border border-green-200 rounded-lg text-center">
                    <p className="text-green-800 text-sm font-bold">Process Completed!</p>
                  </div>
                )}
              </div>
            </div>
          </section>

          {/* Activity Logs */}
          <section className="bg-slate-900 text-slate-300 p-4 rounded-2xl shadow-inner h-[400px] overflow-y-auto font-mono text-xs">
