        </div>

        {/* Right Column: Preview Area */}
        <div className="lg:col-span-8 flex flex-col gap-6">
          {/* Main Preview */}
          <section className="bg-white rounded-2xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
            <div className="border-b border-slate-100 p-4 bg-slate-50 flex justify-between items-center">
              <h2 className="font-semibold text-slate-700">Report Preview</h2>
              <div className="flex gap-2">
                <span className="text-xs bg-slate-200 px-2 py-1 rounded text-slate-600">HTML Content</span>
                <span className="text-xs bg-slate-200 px-2 py-1 rounded text-slate-600">600px Max Width</span>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-100 flex justify-center">
              {report ? (
                <div className="bg-white shadow-xl overflow-hidden rounded-xl h-fit max-w-[600px] w-full">
                   <div className="bg-red-50 p-3 border-b border-red-100 text-xs text-red-800 italic">
                      Subject: 📈 基金市場報告 - {report.dateStr}
                   </div>
                   <div className="p-6 text-sm text-slate-600">
                     親愛的 <strong>Recipient Name</strong> 您好，
                   </div>
                   <div dangerouslySetInnerHTML={{ __html: report.htmlContent }} />
                   <div dangerouslySetInnerHTML={{ __html: FOOTER_DISCLAIMER_HTML }} />
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-400 text-center">
                  <svg className="w-16 h-16 mb-4 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                  <p className="text-lg font-medium">No report generated yet</p>
                  <p className="text-sm max-w-xs">Complete the data gathering and analysis steps to see the draft report here.</p>
                </div>
              )}
            </div>
          </section>

          {/* Data Source List */}
          {news.length > 0 && !report && (
            <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <h3 className="text-lg font-semibold mb-4 text-slate-700">Identified Market Sources</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {news.map((item, idx) => (
                  <div key={idx} className="p-3 bg-slate-50 rounded-lg border border-slate-100 hover:border-red-200 transition-colors">
                    <h4 className="text-sm font-bold text-slate-800 line-clamp-1 mb-1">{item.title}</h4>
                    <p className="text-xs text-slate-500 line-clamp-2">{item.description}</p>
                    <div className="mt-2 flex justify-between items-center">
                       <span className="text-[10px] text-slate-400 font-mono">{new Date(item.pubDate).toLocaleDateString()}</span>
                       <a href={item.link} target="_blank" rel="noopener noreferrer" className="text-[10px] text-red-600 font-bold hover:underline uppercase">View Source</a>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          )}

          {/* Recipients List */}
          <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
             <h3 className="text-lg font-semibold mb-4 text-slate-700 flex items-center justify-between">
                Email Recipients
                <span className="text-xs bg-slate-100 px-2 py-1 rounded font-normal text-slate-500">{RECIPIENTS_LIST.length} total</span>
             </h3>
             <div className="flex flex-wrap gap-2">
                {RECIPIENTS_LIST.map((r, i) => (
                  <div key={i} className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-xs ${i === 0 ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
                    <div className={`w-2 h-2 rounded-full ${i === 0 ? 'bg-blue-500' : 'bg-slate-300'}`}></div>
                    <span className="font-bold">{r.name}</span>
                    <span className="opacity-60">{r.email}</span>
                    {i === 0 && <span className="bg-blue-600 text-white px-1.5 rounded text-[8px] uppercase font-black">Admin</span>}
                  </div>
                ))}
             </div>
          </section>
        </div>
      </main>

      {/* Error Toast */}
      {error && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-red-600 text-white px-6 py-3 rounded-xl shadow-2xl flex items-center gap-3 animate-bounce">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <span className="font-medium">{error}</span>
          <button onClick={() => setError(null)} className="ml-2 hover:opacity-70">✕</button>
        </div>
      )}
    </div>
  );
};

export default App;

payload.text:
// ==========================================
// 1. 全域設定區
// ==========================================

// 建議將 API KEY 移至專案設定的 Script Properties，避免直接寫在程式碼中
const DEFAULT_API_KEY = 'AIzaSyABTQCFYSIBmzuu9KuxAicrcW9rTxvP1tM'; 

const RECIPIENTS_LIST = [
  { email: 'jerry.hung@cmoneyfund.com.tw', name: '洪國寶' },
  { email: 'nancy.chen@cmoneyfund.com.tw', name: '陳亮君' },  // 可以在此新增更多收件人
];

const SENDER_NAME = "CMoneyFund"; 

// --- 搜尋參數 ---
const GOOGLE_NEWS_BASE = 'https://news.google.com/rss/search?q=';
const QUERY_SITES = '(site:news.cnyes.com/ OR site:fund.cnyes.com/IPO/ OR site:cmoney.tw/notes/?navId=cmoney_official OR site:moneydj.com/funddj/fundMarket.djhtm?a=broncho-1 OR site:fundsin.com.tw OR site:macromicro.me OR site:stockfeel.com.tw OR site:udn.com/news/cate/2/6645 OR site:finance.technews.tw OR site:fx168news.com OR finance.ettoday.net OR tw.stock.yahoo.com OR ctee.com.tw/livenews OR site:tw.tradingview.com/news/providers/reuters/ OR site:money.udn.com/money/vipbloomberg/time?edn_newestlist_vipbloomberg OR site:zh.cn.nikkei.com/ OR today.line.me/tw/ OR site:ctee.com.tw/wealth/fund OR site:news.google.com)';
const QUERY_KEYWORDS = '(intitle:資金流向 OR intitle:加碼 OR intitle:減碼 OR intitle:申購 OR intitle:贖回 OR intitle:募集 OR intitle:規模) AND (基金 OR ETF OR 債券 OR 股票型 OR 科技股 OR 美債 OR 高收益 OR AI OR 半導體 OR 機器人 OR 算力 OR 川普 OR 貿易戰 OR 關稅 OR 降息 OR 軟著陸 OR 地緣政治 OR 中東 OR 油價) AND (基金 OR ETF OR 投資展望 OR 經理人 OR 研報)';
const QUERY_PARAMS = 'when:2d&hl=zh-TW&gl=TW&ceid=TW:zh-Hant';

// ==========================================
// 2. 主程式邏輯
// ==========================================

function dailyAutoNews() {
  try {
    Logger.log("開始執行每日基金市場分析報告自動化流程...");

    const scriptProperties = PropertiesService.getScriptProperties();
    let apiKey = scriptProperties.getProperty('GEMINI_API_KEY') || DEFAULT_API_KEY;

    if (!apiKey) throw new Error("請設定有效的 Gemini API Key！");

    const today = new Date();
    const dateStr = Utilities.formatDate(today, Session.getScriptTimeZone(), "yyyy/MM/dd"); 
    let newsData = "";
    let fetchCount = 0;

    const encodedQuery = encodeURIComponent(`${QUERY_SITES} ${QUERY_KEYWORDS}`);
    const finalUrl = `${GOOGLE_NEWS_BASE}${encodedQuery}&${QUERY_PARAMS}`;

    Logger.log("正在抓取新聞...");
    const response = UrlFetchApp.fetch(finalUrl, {muteHttpExceptions: true});
    const xmlContent = sanitizeXml(response.getContentText());
    const document = XmlService.parse(xmlContent);
    const root = document.getRootElement();
    const items = root.getChild('channel').getChildren('item');

    // [修正] 建議限制為<15則
    const maxItems = 12;

    for (let i = 0; i < Math.min(items.length, maxItems); i++) {
      const item = items[i];
      const title = item.getChildText('title');
      // [修正] 摘要維持 100 字精簡版，節省 Token
      let desc = (item.getChildText('description') || "").replace(/<[^>]+>/g, '').trim().substring(0, 100);

      if (title && title.length > 5) {
        newsData += `[${i+1}] ${title}\n摘要: ${desc}\n---\n`;
        fetchCount++;
      }
    }

    if (fetchCount < 3) return Logger.log("資料過少，略過執行。");
    Logger.log(`共抓取到 ${fetchCount} 則新聞，準備呼叫 AI...`);

    // --- 步驟 B: 呼叫 Gemini AI ---
    const prompt = `
你是一個專業的基金經理人，請製作一份「基金市場報告」。讀者為基金投資客戶。

**核心指令：**
1. 根據新聞資料，**挑選 4-5 個最重要的市場議題**進行分析。
2. **務必確保 HTML 標籤完整閉合**，若篇幅不夠，請優先結束文章，不要斷在 HTML 結構中。
3. 全文長度控制在 **900-1000 字**。
4. 全文不提及特定加密貨幣，以數位資產替代。
5. **最後的投資建議區塊，務必列舉 3-5 檔相關的具體基金名稱，並列示投資理由。**

**HTML 格式要求（純 HTML，無 Markdown）：**

<div style="max-width: 600px; margin: 20px auto; font-family: 'Microsoft JhengHei', Arial, sans-serif; color: #444; line-height: 1.7; border: 1px solid #eee; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.05);">
  <!-- 標題區 -->
  <div style="background-color: #990000; padding: 40px 20px; text-align: center;">
    <div style="color: #fff; font-size: 16px; font-weight: bold;">基金市場報告</div>
    <!-- 明確指令：生成副標題 -->
    <div style="color: #fff; font-size: 18px; font-weight: bold; margin-top: 5px;">請根據內文生成一個 18 字以內的創意副標題</div>
    <div style="color: rgba(255,255,255,0.9); font-size: 14px; margin-top: 10px;">${dateStr}</div>
  </div>

  <!-- 引言 -->
  <div style="padding: 30px 25px 10px 25px;">
      請在此處撰寫約 100 字的市場總覽，重點使用 <strong style="color: #990000;">關鍵字</strong> 標示。
      **內文不需要招呼詞（如：各位尊敬的基金投資客戶）
  </div>

  <!-- 內容卡片 (請生成 4-5 張) -->
  <!-- 範例卡片結構 (請重複此結構) -->
  <div style="background-color: #f2f2f2; border-radius: 12px; padding: 20px; margin: 15px 25px; border: 1px solid #f0f0f0;">
    <div style="font-size: 18px; color: #990000; font-weight: bold; margin-bottom: 10px;">1. 議題標題</div>
    <div>內文分析...重點數據使用 <strong style="color: #990000;">紅色高亮</strong>。</div>
  </div>

  <!-- 精選基金 -->
  <div style="background-color: #f2f2f2; border-radius: 12px; padding: 20px; margin: 15px 25px; border: 1px solid #f0f0f0;">
    <div style="font-size: 18px; color: #990000; font-weight: bold; margin-bottom: 10px;">精選基金投資</div>
    <div>請根據分析提供投資策略，並<strong style="color: #990000;">務必列舉 3-5 檔相關的具體基金名稱，並列示投資理由</strong>作為參考。</div>
  </div>
</div>

【新聞資料】：
${newsData}`;

    // 使用重試機制呼叫 AI
    const aiResponse = callGeminiWithRetry(prompt, apiKey);

    if (!aiResponse || aiResponse.length < 500) {
        throw new Error("Gemini 回傳內容異常，取消發送。");
    }

    // 檢查結尾，嘗試修復截斷
    let finalContent = aiResponse;
    if (!finalContent.trim().endsWith('</div>') && !finalContent.trim().endsWith('>')) {
        Logger.log("警告：內容截斷，嘗試自動修復 HTML 結構。");
        finalContent += "</div></div>"; 
    } else {
        Logger.log("HTML 結構檢查通過。");
    }

    // --- 發送郵件迴圈 ---
    RECIPIENTS_LIST.forEach(recipient => {
      const greetingHtml = `
        <div style="max-width: 600px; margin: 30px auto 0 auto; font-family: 'Microsoft JhengHei', Arial, sans-serif; color: #333; font-size: 16px; padding-left: 10px;">
          親愛的 <strong>${recipient.name}</strong> 您好，
        </div>`;

      const finalHtmlBody = greetingHtml + finalContent + FOOTER_DISCLAIMER_HTML;

      MailApp.sendEmail({
        to: recipient.email,
        name: SENDER_NAME,
        subject: `📈 基金市場報告 - ${dateStr}`,
        htmlBody: finalHtmlBody
      });
      Logger.log(`郵件已發送至: ${recipient.name}`);
    });

  } catch (e) {
    Logger.log("執行嚴重錯誤: " + e.toString());
    MailApp.sendEmail({
        to: "jerry.hung@cmoneyfund.com.tw",
        subject: "❌ 腳本執行錯誤警告",
        body: "錯誤訊息: " + e.toString()
    });
  }
}

// ==========================================
// 3. 輔助函式區
// ==========================================

const FOOTER_DISCLAIMER_HTML = `
    <div style="max-width: 600px; margin: 30px auto; font-family: 'Microsoft JhengHei', Arial, sans-serif; border-top: 1px solid #ddd; padding-top: 20px;">
      <div style="font-size: 12px; color: #999999; line-height: 1.6; text-align: justify; padding: 0 20px;">
        <strong>【投資警語】</strong><br>
        1. 投資一定有風險，基金投資有賺有賠，申購前應詳閱基金公開說明書。<br>
        2. 基金經金管會核准或同意生效，惟不表示絕無風險。基金經理公司以往之經理績效不保證基金之最低投資收益。<br>
        3. 本文提及之經濟走勢預測不必然代表本基金之績效。<br>
        <br>
        © 口袋證券投資顧問股份有限公司
      </div>
    </div>
`;

function sanitizeXml(xmlContent) {
  return xmlContent.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g, '');
}

function callGeminiAPI(prompt, apiKey) {
  // [修正 1] 使用正確的模型名稱與半形冒號
  const modelName = "gemini-2.5-flash"; // 或是 "gemini-2.0-flash"
  const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${apiKey}`;

  const payload = {
    "contents": [{ "parts": [{ "text": prompt }] }],
    "generationConfig": { 
      "temperature": 0.4,
      "maxOutputTokens": 8192 
    },
    "safetySettings": [
        { "category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE" },
        { "category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE" },
        { "category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE" },
        { "category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE" }
    ]
  };

  const options = {
    "method": "post",
    "contentType": "application/json",
    "payload": JSON.stringify(payload),
    "muteHttpExceptions": true // 這樣才能抓到 400/429 錯誤的內容
  };

  try {
    const response = UrlFetchApp.fetch(GEMINI_URL, options);
    const jsonText = response.getContentText();

    // [修正 2] 增加內容檢查，避免解析非 JSON 格式
    if (!jsonText || jsonText.startsWith("<!DOCTYPE")) {
      Logger.log("API 回傳了非 JSON 內容 (可能是 HTML 錯誤頁面): " + jsonText.substring(0, 100));
      return null;
    }

    const result = JSON.parse(jsonText);

    if (result.error) {
      Logger.log("API Error: " + JSON.stringify(result.error));
      if (result.error.code === 429) {
        return { status: "QUOTA_EXCEEDED", message: result.error.message };
      }
      return null;
    }

    if (result.candidates && result.candidates[0].content && result.candidates[0].content.parts[0].text) {
      let rawText = result.candidates[0].content.parts[0].text;

      // 去除 AI 可能自動加上的 Markdown 標籤
      return rawText.replace(/^```html\s*/i, '').replace(/```\s*$/, '').trim();
    } else {
      Logger.log("API 回傳結構未預期: " + jsonText);
      return null;
    }
  } catch (e) {
    Logger.log("fetch 過程發生異常: " + e.message);
    return null;
  }
}

function callGeminiWithRetry(prompt, apiKey) {
  // 基礎等待時間，但會根據 Google 錯誤訊息動態調整
  const waitTimes = [20000, 50000, 90000]; 

  for (let i = 0; i < waitTimes.length; i++) {
    try {
      let result = callGeminiAPI(prompt, apiKey);

      // [修正] 確保能讀取到 callGeminiAPI 回傳的 QUOTA_EXCEEDED 物件
      if (typeof result === 'object' && result !== null && result.status === "QUOTA_EXCEEDED") {
         let waitTime = waitTimes[i];

         // 智慧解析 Google 建議的等待時間
         const match = result.message && result.message.match(/retry in ([0-9.]+)s/);
         if (match && match[1]) {
             waitTime = (Math.ceil(parseFloat(match[1])) + 5) * 1000;
         }

         Logger.log(`配額不足 (429)，系統建議等待: ${match ? match[1] + 's' : '未知'}，將暫停 ${waitTime/1000} 秒後重試...`);
         Utilities.sleep(waitTime);
         continue; 
      }

      if (typeof result === 'string' && result.trim() !== "") {
        return result;
      }

    } catch (e) {
      Logger.log(`第 ${i + 1} 次呼叫發生例外: ${e.message}`);
    }

    if (i < waitTimes.length - 1) {
        Logger.log(`等待 ${waitTimes[i]/1000} 秒後重試...`);
        Utilities.sleep(waitTimes[i]);
    }
  }
  throw new Error("Gemini API 多次重試後仍失敗");
}

