import { GoogleGenAI } from "@google/genai";
import { NewsItem } from '../types';

export const generateMarketReport = async (newsItems: NewsItem[], dateStr: string): Promise<string> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("系統未偵測到有效的 API Key，請確認環境設定。");
  }

  const ai = new GoogleGenAI({ apiKey });

  const newsContext = newsItems.map((item, idx) => `
    [新聞 ${idx + 1}] ${item.title}
    摘要: ${item.description.substring(0, 100)}
    ---
  `).join('\n');

  const prompt = `
你是一個專業的基金經理人，請製作一份「基金市場報告」。讀者為基金投資客戶。

**核心指令：**
1. 根據新聞資料，**挑選 4-5 個最重要的市場議題**進行分析。
2. **務必確保 HTML 標籤完整閉合**，若篇幅不夠，請優先結束文章，不要斷在 HTML 結構中。
3. 全文長度控制在 **900-1000 個中文字** 左右。
4. **全文不提及特定加密貨幣名稱（如：比特幣、以太幣），請以「數位資產」替代。**
5. **最後的投資建議區塊，務必列舉 3-5 檔相關的具體基金名稱，並列示投資理由。**
6. 請直接輸出 HTML 代碼，不要包含任何 Markdown 格式。

**HTML 格式要求：**

<div style="max-width: 600px; margin: 20px auto; font-family: 'Microsoft JhengHei', Arial, sans-serif; color: #444; line-height: 1.7; border: 1px solid #eee; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.05);">
  <!-- 標題區 -->
  <div style="background-color: #990000; padding: 40px 20px; text-align: center;">
    <div style="color: #fff; font-size: 16px; font-weight: bold;">基金市場報告</div>
    <div style="color: #fff; font-size: 18px; font-weight: bold; margin-top: 5px;">[請生成一個 18 字以內的創意副標題]</div>
    <div style="color: rgba(255,255,255,0.9); font-size: 14px; margin-top: 10px;">${dateStr}</div>
  </div>

  <!-- 引言 -->
  <div style="padding: 30px 25px 10px 25px;">
      [在此撰寫約 100 字的市場總覽，重點數據使用 <strong style="color: #990000;">紅色高亮</strong>。不需要招呼語。]
  </div>

  <!-- 內容卡片 -->
  <div style="background-color: #f2f2f2; border-radius: 12px; padding: 20px; margin: 15px 25px; border: 1px solid #f0f0f0;">
    <div style="font-size: 18px; color: #990000; font-weight: bold; margin-bottom: 10px;">議題標題</div>
    <div>內文分析...重點數據使用 <strong style="color: #990000;">紅色高亮</strong>。</div>
  </div>

  <!-- 精選基金 -->
  <div style="background-color: #f2f2f2; border-radius: 12px; padding: 20px; margin: 15px 25px; border: 1px solid #f0f0f0;">
    <div style="font-size: 18px; color: #990000; font-weight: bold; margin-bottom: 10px;">精選基金投資</div>
    <div>請根據分析提供投資策略，並<strong style="color: #990000;">務必列舉 3-5 檔相關的具體基金名稱，並列示投資理由</strong>作為參考。</div>
  </div>
</div>

【新聞資料】：
${newsContext}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        temperature: 0.4,
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("AI 回傳了空內容。");
    }

    return text.replace(/^```html\s*/i, '').replace(/```\s*$/, '').trim();
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    if (error.message?.includes("API key not valid")) {
      throw new Error("無效的 API Key。請確認環境變數 API_KEY 已正確配置。");
    }
    throw error;
  }
};

import React, { useState } from 'react';
import { 
  AppStatus, 
  NewsItem, 
  MarketReport 
} from './types';
import { 
  QUERY_SITES, 
  QUERY_KEYWORDS, 
  RECIPIENTS_LIST, 
  PRIMARY_REVIEWER,
  SENDER_NAME,
  FOOTER_DISCLAIMER_HTML
} from './constants';
import { generateMarketReport } from './services/geminiService';

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [news, setNews] = useState<NewsItem[]>([]);
  const [report, setReport] = useState<MarketReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [logs, setLogs] = useState<string[]>([]);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev]);
  };

  const fetchNews = async () => {
    setStatus(AppStatus.FETCHING_NEWS);
    setError(null);
    addLog("正在從 Google RSS 抓取新聞...");

    try {
      const encodedQuery = encodeURIComponent(`${QUERY_SITES} ${QUERY_KEYWORDS}`);
      const proxyUrl = `https://api.rss2json.com/v1/api.json?rss_url=${encodeURIComponent(`https://news.google.com/rss/search?q=${encodedQuery}&when:2d&hl=zh-TW&gl=TW&ceid=TW:zh-Hant`)}`;

      const response = await fetch(proxyUrl);
      const data = await response.json();

      if (data.status === 'ok') {
        const items: NewsItem[] = data.items.map((item: any) => ({
          title: item.title,
          description: item.description.replace(/<[^>]+>/g, '').trim(),
          link: item.link,
          pubDate: item.pubDate
        }));
        setNews(items.slice(0, 12));
        addLog(`成功抓取 ${items.length} 則新聞。`);
        setStatus(AppStatus.IDLE);
      } else {
        throw new Error("無法從 RSS 服務獲取數據。");
      }
    } catch (err: any) {
      setError(err.message);
      setStatus(AppStatus.IDLE);
      addLog(`錯誤: ${err.message}`);
    }
  };

  const handleGenerateReport = async () => {
    if (news.length === 0) return;
    setStatus(AppStatus.GENERATING_REPORT);
    setError(null);
    addLog("啟動 AI 市場分析報告生成...");

    try {
      const today = new Date();
      const dateStr = today.toLocaleDateString('zh-TW', { year: 'numeric', month: '2-digit', day: '2-digit' });
      const htmlContent = await generateMarketReport(news, dateStr);

      setReport({ htmlContent, dateStr });
      addLog("報告生成成功，進入待審核狀態。");
      setStatus(AppStatus.REVIEWING);
    } catch (err: any) {
      console.error("Report Generation Failed:", err);
      setError(err.message || "發生未知錯誤，請重試。");
      setStatus(AppStatus.IDLE);
      addLog(`生成失敗: ${err.message}`);
    }
  };

  const sendToPrimary = () => {
    addLog(`正在發送審核郵件至主要審核人: ${PRIMARY_REVIEWER.name}...`);
    setTimeout(() => {
      setStatus(AppStatus.SENT_TO_PRIMARY);
      addLog(`郵件已寄送至 ${PRIMARY_REVIEWER.email}，等待審核。`);
    }, 1500);
  };

  const approveAndSendAll = () => {
    addLog("審核通過！正在將正式報告以密件副本 (BCC) 發送給所有收件人...");
    setTimeout(() => {
      setStatus(AppStatus.COMPLETED);
      addLog("全部發送完畢，工作流程結束。");
    }, 2000);
  };

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setNews([]);
    setReport(null);
    setError(null);
    setLogs([]);
  };

  const getReviewGreeting = (name: string) => {
    const isPartner = name === '投資夥伴';
    return `
      <div style="max-width: 600px; margin: 30px auto 0 auto; font-family: 'Microsoft JhengHei', Arial, sans-serif; color: #333; font-size: 16px; padding-left: 10px;">
        親愛的${isPartner ? '' : ' '}<strong>${name}</strong> 您好：
      </div>
    `;
  };

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-red-800 text-white p-4 shadow-md sticky top-0 z-50 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center text-red-800 font-bold text-xl">CM</div>
          <div>
            <h1 className="text-lg font-bold leading-none tracking-tight">CMoneyFund 市場分析報告系統</h1>
            <p className="text-xs text-red-200">AI-Powered Fund Report Workflow</p>
          </div>
        </div>
        <div className="flex gap-2">
           <button onClick={reset} className="bg-red-900/50 hover:bg-red-900 px-3 py-1 rounded text-sm transition-colors">重設流程</button>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-4 lg:p-8 grid grid-cols-1 lg:grid-cols-12 gap-6">

        <div className="lg:col-span-4 space-y-6">
          <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2 text-slate-800">
              <span className="w-2 h-6 bg-red-600 rounded-full"></span>
              執行流程 (Workflow)
            </h2>

            <div className="space-y-4">
              <div className={`p-4 rounded-xl border-2 transition-all ${news.length > 0 ? 'border-green-100 bg-green-50' : 'border-slate-100 bg-slate-50'}`}>
                <div className="flex justify-between items-center mb-2">
                  <span className="text-sm font-medium text-slate-500 uppercase">1. 抓取資料</span>
                  {news.length > 0 && <span className="text-green-600 text-xs font-bold">✓ 已抓取</span>}
